INSERT OR IGNORE INTO news (id, data, created_at, updated_at, created_by, updated_by) VALUES ('demo-news-1', '{"slug":"demo-1-victoire-des-u17-devant-leur-public","title":"Victoire des U17 devant leur public","category":"Match","excerpt":"Les U17 s''imposent 3 à 1 au stade municipal grâce à un doublé de Jean K.","content":"Les U17 de l''académie ont dominé la rencontre du début à la fin. Après l''ouverture du score en première période, l''équipe a su garder la maîtrise du ballon et conclure avec un troisième but en seconde mi-temps.\n\nLe staff a salué l''état d''esprit du groupe : solidarité, rigueur et plaisir de jouer ensemble.\n\nContenu de démonstration : modifiez-le ou supprimez-le depuis l''espace d''administration.","image":"/demo/news-match.jpg","imageAlt":"Victoire des U17 devant leur public","status":"publie","publishedAt":"2026-10-12T09:00:00.000Z","author":"Communication OKM"}', '2026-10-16T05:24:20.297Z', '2026-10-16T05:24:20.297Z', NULL, NULL);
INSERT OR IGNORE INTO news (id, data, created_at, updated_at, created_by, updated_by) VALUES ('demo-news-2', '{"slug":"demo-2-reprise-des-entrainements-le-programme-de-la-saison","title":"Reprise des entraînements : le programme de la saison","category":"Académie","excerpt":"Horaires, catégories et rendez-vous à noter pour la nouvelle saison.","content":"La saison est lancée. Chaque catégorie retrouve son terrain d''entraînement avec un programme de travail technique, tactique et physique adapté à l''âge des joueurs.\n\nLes familles peuvent consulter les catégories et demander une inscription depuis le site.\n\nContenu de démonstration : modifiez-le ou supprimez-le depuis l''espace d''administration.","image":"/demo/news-training.jpg","imageAlt":"Reprise des entraînements : le programme de la saison","status":"publie","publishedAt":"2026-10-07T09:00:00.000Z","author":"Communication OKM"}', '2026-10-16T05:24:20.297Z', '2026-10-16T05:24:20.297Z', NULL, NULL);
INSERT OR IGNORE INTO news (id, data, created_at, updated_at, created_by, updated_by) VALUES ('demo-news-3', '{"slug":"demo-3-le-trophee-de-la-rentree-reste-a-l-academie","title":"Le trophée de la rentrée reste à l''académie","category":"Événement","excerpt":"Retour sur un tournoi riche en émotions et en beau jeu.","content":"Le tournoi de la rentrée a réuni plusieurs clubs de jeunes de Brazzaville. Nos joueurs ont fini la compétition invaincus.\n\nBravo à tous les participants et merci aux bénévoles qui ont rendu cette journée possible.\n\nContenu de démonstration : modifiez-le ou supprimez-le depuis l''espace d''administration.","image":"/demo/news-trophy.jpg","imageAlt":"Le trophée de la rentrée reste à l''académie","status":"publie","publishedAt":"2026-10-01T09:00:00.000Z","author":"Communication OKM"}', '2026-10-16T05:24:20.297Z', '2026-10-16T05:24:20.297Z', NULL, NULL);
INSERT OR IGNORE INTO news (id, data, created_at, updated_at, created_by, updated_by) VALUES ('demo-news-4', '{"slug":"demo-4-un-nouveau-partenaire-rejoint-l-academie","title":"Un nouveau partenaire rejoint l''académie","category":"Partenaires","excerpt":"Un soutien précieux pour les équipements et les déplacements des équipes.","content":"L''académie accueille un nouveau partenaire qui accompagnera les équipes de jeunes tout au long de la saison.\n\nCe soutien contribuera à l''achat d''équipements et à l''organisation des déplacements.\n\nContenu de démonstration : modifiez-le ou supprimez-le depuis l''espace d''administration.","image":"/demo/news-stadium.jpg","imageAlt":"Un nouveau partenaire rejoint l''académie","status":"publie","publishedAt":"2026-09-25T09:00:00.000Z","author":"Communication OKM"}', '2026-10-16T05:24:20.297Z', '2026-10-16T05:24:20.297Z', NULL, NULL);
INSERT OR IGNORE INTO news (id, data, created_at, updated_at, created_by, updated_by) VALUES ('demo-news-5', '{"slug":"demo-5-seance-speciale-tirs-au-but","title":"Séance spéciale tirs au but","category":"Académie","excerpt":"Les gardiens et attaquants travaillent la précision et le sang-froid.","content":"Une séance consacrée aux tirs au but a rassemblé les gardiens et les attaquants de plusieurs catégories.\n\nObjectif : apprendre à gérer la pression et à rester concentré jusqu''au dernier tir.\n\nContenu de démonstration : modifiez-le ou supprimez-le depuis l''espace d''administration.","image":"/demo/news-goal.jpg","imageAlt":"Séance spéciale tirs au but","status":"publie","publishedAt":"2026-09-18T09:00:00.000Z","author":"Communication OKM"}', '2026-10-16T05:24:20.297Z', '2026-10-16T05:24:20.297Z', NULL, NULL);
INSERT OR IGNORE INTO news (id, data, created_at, updated_at, created_by, updated_by) VALUES ('demo-news-6', '{"slug":"demo-6-journee-portes-ouvertes-brouillon","title":"Journée portes ouvertes (brouillon)","category":"Académie","excerpt":"Brouillon non publié : il n''apparaît pas sur le site.","content":"Texte en préparation. Passez le statut sur « Publié » depuis l''administration pour l''afficher sur le site.\n\nContenu de démonstration : modifiez-le ou supprimez-le depuis l''espace d''administration.","image":"/demo/gallery-6.jpg","imageAlt":"Journée portes ouvertes (brouillon)","status":"brouillon","publishedAt":null,"author":"Communication OKM"}', '2026-10-16T05:24:20.297Z', '2026-10-16T05:24:20.297Z', NULL, NULL);
