INSERT OR IGNORE INTO site_settings (id, data, created_at, updated_at, created_by, updated_by) VALUES ('site', '{"heroLead":"OKM Football Académie accompagne la formation et le développement des jeunes footballeurs de Brazzaville.","heroImage":"/demo/hero.jpg","academieMission":"OKM Football Académie forme de jeunes joueurs à Brazzaville. Notre mission : permettre à chaque enfant de progresser au football dans un cadre sûr, exigeant et bienveillant.\n\nNous croyons que le sport est une école de vie : respect, discipline, esprit d''équipe et persévérance.\n\nContenu de démonstration : modifiez-le ou supprimez-le depuis l''espace d''administration.","academieTeam":"","email":"okmfootballaca@gmail.com","facebookName":"OKM football Académie","facebookUrl":""}', '2026-10-16T05:24:20.297Z', '2026-10-16T05:24:20.297Z', NULL, NULL);
